# heart_rate_logger.py
# Reads heart rate and SpO2 from a MAX30102 sensor over I2C on a Raspberry Pi.
# Logs data to a file and prints it to the console.

import time
import smbus2
import board
import busio
import adafruit_max30102

# I2C address of the MAX30102 sensor
MAX30102_ADDRESS = 0x57

# Log file name
LOG_FILE = "heart_rate_log.txt"

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the MAX30102 sensor."""
    try:
        sensor = adafruit_max30102.MAX30102(i2c_bus, address=MAX30102_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads heart rate and SpO2 data from the sensor."""
    try:
        ir_data = sensor.get_ir_data()
        red_data = sensor.get_red_data()
        return ir_data, red_data
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def estimate_heart_rate(ir_data, red_data):
    """Estimates heart rate from IR and RED ADC readings."""
    if ir_data is None or red_data is None:
        return None

    # Simple peak-counting based heart-rate estimation
    # Replace with a more sophisticated algorithm if needed
    # This is a placeholder for a more advanced algorithm
    heart_rate = 60 + (ir_data - red_data) * 5  # Example formula
    return heart_rate

def log_data(log_file, timestamp, heart_rate, spo2):
    """Logs the data to a file."""
    try:
        with open(log_file, "a") as file:
            file.write(f"{timestamp},Heart Rate: {heart_rate},SpO2: {spo2}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            ir_data, red_data = read_sensor_data(sensor)
            if ir_data is not None and red_data is not None:
                heart_rate = estimate_heart_rate(ir_data, red_data)
                if heart_rate is not None:
                    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                    log_data(LOG_FILE, timestamp, heart_rate, "N/A")  # Placeholder for SpO2
                    print(f"Timestamp: {timestamp}, Heart Rate: {heart_rate}")
            time.sleep(1)  # Sample every 1 second
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or the sensor object
        pass

if __name__ == "__main__":
    main()

