#!/usr/bin/python3
# face detection on the Raspberry Pi camera with OpenCV
import time
import cv2
from picamera2 import Picamera2

# Load the Haar cascade classifier for face detection
face_detector = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')

def initialize_camera():
    """Initialize the Raspberry Pi camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (450, 450)}))
        camera.start()
        time.sleep(2)  # Allow camera to warm up
        return camera
    except Exception as e:
        print(f"Camera initialization failed: {e}")
        return None

def detect_faces(image_frame):
    """Detect faces in a given image frame."""
    gray_frame = cv2.cvtColor(image_frame, cv2.COLOR_BGR2GRAY)
    faces = face_detector.detectMultiScale(gray_frame, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
    return faces

def draw_face_rectangles(image_frame, faces):
    """Draw rectangles around detected faces in the image."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image_frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

def main():
    """Main function to capture and process video frames."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        while True:
            image = camera.capture_array()
            if image is None:
                continue  # Skip frame if capture fails

            faces = detect_faces(image)
            draw_face_rectangles(image, faces)

            cv2.imshow('Frame', image)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        camera.stop()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

