import time
import RPi.GPIO as GPIO
import gpiozero

# Pin definitions using BCM numbering
BUTTON_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]

# Polling interval in seconds
POLL_INTERVAL = 0.05

def setup_gpio():
    """Initialize GPIO pins and output devices."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in BUTTON_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        for pin in OUTPUT_PINS:
            GPIO.output(pin, GPIO.LOW)
            GPIO.setup(pin, GPIO.OUT)
    except Exception as e:
        raise RuntimeError("GPIO setup failed: {}".format(e))

def read_button_states():
    """Read the current state of all button pins."""
    return [GPIO.input(pin) for pin in BUTTON_PINS]

def update_outputs(button_states):
    """Update the output devices based on button states."""
    try:
        led = gpiozero.OutputDevice(OUTPUT_PINS[1], active_high=True, initial_value=False)
        for i, is_pressed in enumerate(button_states):
            if is_pressed:
                GPIO.output(OUTPUT_PINS[0], GPIO.HIGH)
                led.value = False
            else:
                GPIO.output(OUTPUT_PINS[0], GPIO.LOW)
                led.value = True
    except Exception as e:
        raise RuntimeError("Output update failed: {}".format(e))


def main():
    """Main program loop."""
    try:
        setup_gpio()
        last_button_state = [False] * len(BUTTON_PINS)
        output_state = 0

        while True:
            current_button_state = read_button_states()
            if current_button_state != last_button_state:
                update_outputs(current_button_state)
                last_button_state = current_button_state.copy()  # Store a copy to avoid modification during iteration

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print("An unexpected error occurred: {}".format(e))
    finally:
        GPIO.cleanup()  # Release GPIO resources


if __name__ == "__main__":
    main()

