# temperature_monitor.py
# Reads and prints the CPU temperature of a Raspberry Pi 4 Model B.
# Uses gpiozero for a clean and robust entry point.

import time
from gpiozero import CPUTemperature

def read_cpu_temperature():
    """Reads the CPU temperature and returns it as a float."""
    try:
        cpu_device = CPUTemperature()  # Create the temperature sensor object
        return cpu_device.temperature
    except FileNotFoundError:
        print("Warning: Could not read CPU temperature. Thermal sensor file not found.")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def main():
    """Main function to continuously read and print the CPU temperature."""
    print("Starting CPU temperature monitoring...")
    try:
        while True:
            temperature_value = read_cpu_temperature()
            if temperature_value is not None:
                print(f"CPU Temperature: {temperature_value:.2f} °C")
            time.sleep(5)  # Wait 5 seconds before the next reading
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting temperature monitoring...")

if __name__ == "__main__":
    main()

