# altitude_logger_procedural.py
# Reads pressure and altitude from a BMP280 sensor over I2C on a Raspberry Pi.
# Logs data to a file for environmental science applications.

import time
import board
import busio
import adafruit_bmp280
import datetime

# Configuration
I2C_ADDRESS = 0x76  # BMP280 I2C address
SEA_LEVEL_PRESSURE = 1013.25  # Standard sea level pressure in hPa
LOG_FILE = "altitude_log.txt"

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.BMP280_I2C(i2c_bus, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def read_sensor_data(sensor):
    """Reads pressure and altitude from the sensor."""
    try:
        pressure = sensor.pressure
        altitude = sensor.altitude
        return pressure, altitude
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def log_data(log_file, timestamp, pressure, altitude):
    """Logs the data to the specified file."""
    try:
        with open(log_file, "a") as file:
            file.write(f"{timestamp} - Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            timestamp = datetime.datetime.now().isoformat()
            pressure, altitude = read_sensor_data(sensor)

            if pressure is not None and altitude is not None:
                print(f"Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters")
                log_data(LOG_FILE, timestamp, pressure, altitude)
            else:
                print("Failed to read sensor data.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or the sensor object
        pass

if __name__ == "__main__":
    main()

