#!/usr/bin/env python3

"""
Raspberry Pi UPS Plus Demo Code (Object-Oriented)

This script demonstrates the functionalities of the UPS Plus HAT using an object-oriented approach.
It reads various parameters such as voltage, current, temperature, and power status
from both the power supply and the battery. It also showcases how to set certain
parameters like protection voltage, sampling period, and power state.

Advanced users can customize and develop this code to meet their specific needs.
"""

import time
import smbus2
import logging
from ina219 import INA219, DeviceRangeError

# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
DEVICE_BUS = 1  # I2C bus number
DEVICE_ADDRESS = 0x17  # I2C address of the UPS Plus HAT
BATT_INA219_ADDRESS = 0x45  # I2C address of the battery INA219 sensor
SHUNT_RESISTANCE = 0.005  # Shunt resistance for the battery INA219 (Ohms)
SUPPLY_INA219_ADDRESS = 0x40  # I2C address of the power supply INA219 sensor
SUPPLY_SHUNT_RESISTANCE = 0.00725 # Shunt resistance for the power supply INA219 (Ohms)
SAMPLE_PERIOD_MIN = 2  # Default sampling period in minutes

# Initialize logging with formatter
log_format = "%(asctime)s - %(levelname)s - %(message)s"
logging.basicConfig(level=logging.INFO, format=log_format)


class SensorBase:
    """Base class for sensors, providing common methods."""

class INA219Sensor(SensorBase):
    """Base class for INA219 sensors, providing common methods."""

class UPSPlus:
    """Class to represent the UPS Plus HAT."""

    def __init__(self, bus_number=DEVICE_BUS, device_address=DEVICE_ADDRESS):
        """Initializes the UPSPlus object."""
        self.bus = smbus2.SMBus(bus_number)
        self.device_address = device_address
        self.supply_ina = None
        self.batt_ina = None
        self._initialize_sensors()

    def _initialize_sensors(self):
        """Initializes the INA219 sensors for power supply and battery."""
        try:
            self.supply_ina = INA219(SHUNT_RESISTANCE, busnum=bus_number, address=SUPPLY_INA219_ADDRESS)
            self.supply_ina.configure()
            logging.info("Power Supply INA219 sensor initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize Power Supply INA219: {e}")
            self.supply_ina = None

        try:
            self.batt_ina = INA219(SHUNT_RESISTANCE, busnum=bus_number, address=BATT_INA219_ADDRESS)
            self.batt_ina.configure()
            logging.info("Battery INA219 sensor initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize Battery INA219: {e}")
            self.batt_ina = None

    def get_ina_data(self, ina):
        """Generic function to read data from INA219 sensor."""
        if ina is None:
            logging.warning("INA219 sensor is not initialized.")
            return None, None

        try:
            voltage = ina.voltage()
            current = ina.current()
            power = ina.power()
            return voltage, current, power
        except Exception as e:
            logging.error(f"Error reading data from INA219: {e}")
            return None, None, None

    def get_supply_data(self):
        """Reads and prints power supply data."""
        voltage, current, power = self.get_ina_data(self.supply_ina)
        if voltage is not None and current is not None and power is not None:
            logging.info("Raspberry Pi power supply voltage: %.3f V", voltage)
            logging.info("Current current consumption of Raspberry Pi: %.3f mA", current)
            logging.info("Current power consumption of Raspberry Pi: %.3f mW", power)

    def get_battery_data(self):
        """Reads and prints battery data."""
        voltage, current, power = self.get_ina_data(self.batt_ina)
        if voltage is not None and current is not None and power is not None:
            logging.info("Battery voltage: %.3f V", voltage)
            try:
                if current > 0:
                    logging.info("Battery current (charging): %.3f mA", current)
                    logging.info("Current battery power: %.3f mW", power)
                else:
                    logging.info("Battery current (discharging): %.3f mA", current)
                    logging.info("Current battery power: %.3f mW", power)
            except DeviceRangeError:
                logging.info("Battery power: Too high to measure")


    def read_register_block(self, register, length):
        """Reads a block of bytes from the UPS Plus HAT register."""
        try:
