# -*- coding: utf-8 -*-

"""
Control an LED via an MCP23017 I2C GPIO expander on a Raspberry Pi Model A.
"""

import time
import smbus2

# I2C address of the MCP23017 expander
MCP23017_ADDRESS = 0x20

# I2C bus number (usually 1 on Raspberry Pi)
I2C_BUS_NUMBER = 0  # or 1, depending on your setup


class MCP23017:
    """Represents an MCP23017 I2C GPIO expander."""

    def __init__(self, address=MCP23017_ADDRESS, busnum=I2C_BUS_NUMBER):
        try:
            self.bus = smbus2.SMBus(busnum)
        except Exception:
            self.bus = None
        self.address = address

    def _write_register(self, register, value):
        """Write a value to a specific register."""
        if not self.bus:
            raise IOError("I2C bus not initialized")
        try:
            self.bus.write_byte_data(self.address, register, value)
        except Exception:
            raise IOError(f"Failed to write to register {register:02X}")

    def _read_register(self, register):
        """Read a value from a specific register."""
        if not self.bus:
            raise IOError("I2C bus not initialized")
        try:
            return self.bus.read_byte_data(self.address, register)
        except Exception:
            raise IOError(f"Failed to read from register {register:02X}")


    def configure_pin(self, pin, mode, pull_up_down=None):
        """Configure a pin as input or output."""
        if pin < 0 or pin > 7:
            raise ValueError("Pin number must be between 0 and 7")

        if mode not in ("output", "input"):
            raise ValueError("Mode must be 'output' or 'input'")

        register_a = 0x00 if mode == "output" else 0x01
        self._write_register(register_a, register_a)  # Set direction

        if pull_up_down is not None:
