# I2C bus number (usually 1 on Raspberry Pi)
I2C_BUS_NUMBER = 0  # or 1, depending on your setup


class MCP23017:
    """Represents an MCP23017 I2C GPIO expander."""

    def __init__(self, address=MCP23017_ADDRESS, busnum=I2C_BUS_NUMBER):
        try:
            self.bus = smbus2.SMBus(busnum)
        except Exception:
