import sys
import threading
import time
import RPi.GPIO as GPIO
import signal
from dogoval import DOG, Eject

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # Seconds

# Global variables
server_running = True
log_file_path = DEFAULT_LOG_FILE
dog = None
receive_thread = None

# --- Helper Functions ---

def log_message(message):
    """Writes a message to the log file."""
    try:
        with open(log_file_path, 'a') as f:
            f.write(message + "\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def initialize_gpio():
    """Initializes the GPIO pins."""
    try:
        GPIO.setmode(GPIO.BCM)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Cleans up the GPIO pins."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")

def create_dog():
    """Creates and configures the DOG object."""
    global dog
    try:
        dog = DOG()
        dog.subscribe(lambda m: receive_callback(m))
        return True
    except Exception as e:
        print(f"Error creating DOG: {e}")
        return False

def receive_callback(message):
    """Callback function for the DOG subscription."""
    if server_running:
        try:
            dog.receive()
        except Exception as e:
            print(f"Error receiving data: {e}")

def start_server():
    """Starts the main server loop."""
    global server_running, log_file_path, receive_thread, dog
    server_running = True

    # Handle command-line arguments
    i = 1
    while i < len(sys.argv):
        if sys.argv[i] == "-l" and i + 1 < len(sys.argv):
            log_file_path = sys.argv[i + 1]
            i += 2
        elif sys.argv[i] == "-s":
            i += 1
        elif sys.argv[i] == "--help":
            print_help()
            server_running = False
            return
        else:
            print_help()
            server_running = False
            return

    if not create_dog():
        print_help()
        server_running = False
        return

    initialize_gpio()
    log_message("Server started")

    # Start the receive thread
    receive_thread = threading.Thread(target=receive_loop, daemon=True)
    receive_thread.start()

    # Keep the main thread alive until interrupted
    while server_running:
        time.sleep(1)

def stop_server(signal_number=None, frame=None):
    """Stops the server and cleans up."""
    global server_running, receive_thread, log_file_path
    server_running = False
    log_message("Server stopped")

    if receive_thread:
        receive_thread.join(timeout=2)  # Wait for thread to finish (with a timeout)
        if receive_thread.is_alive():
            receive_thread.join()  # Ensure thread is fully stopped

    cleanup_gpio()
    sys.exit(0)

def print_help():
    """Prints command-line help information."""
    print("\nUsage: python script.py [-s] [-l <log_file_path>] [-h]")
    print("   -s             Starts the server (optional)")
    print("   -l <log_file_path>  Specifies the log file path (optional)")
    print("   -h or --help    Displays this help information")
    print("Example:")
    print(f"  python script.py -s -l data.log  # Starts the server and logs to data.log")
    print(f"  python script.py -h             # Displays this help information")

def send_data(data):
    """Sends data using the DOG."""
    if not server_running:
        print("Server not running. Use 'python script.py -s' to start.")
        return
    try:
        dog.send(data)
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    """Writes data directly to the log file."""
    if not server_running:
        print("Server not running. Use 'python script.py -s' to start.")
        return
    try:
        with open(log_file_path, 'a') as f:
            f.write(data + "\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def receive_loop():
    """Continuously receives data from the DOG."""
    while server_running:
        try:
            if dog.has_new_message():
                message = dog.next_message()
                log_message(message)
        except Exception as e:
            print(f"Error in receive loop: {e}")
        time.sleep(POLL_INTERVAL)

# --- Main Functions ---

def handle_write(message):
    """Handles the 'write' command."""
    if server_running:
        send_data("WRITE " + message + "\n")
    else:
        print("Server not running. Use 'python script.py -s' to start.")

def handle_start(message):
    """Handles the 'start' command."""
    if server_running:
        print("Server already running.")
        return
    if not create_dog():
        print("Failed to create DOG object. Check logs.")
        return
    global log_file_path
    if len(message) > 1 and message[1] == "-l":
        try:
            log_file_path = message[2]
        except IndexError:
            print("Missing log file path after -l. Using default.")
            log_file_path = DEFAULT_LOG_FILE
    start_server()

def handle_display(message):
    """Handles the 'display' command."""
    if not server_running:
        print("Server not running. Use 'python script.py -s' to start.")
        return
    try:
        with open(log_file_path, 'r') as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except Exception as e:
        print(f"Error reading log file: {e}")

def handle_exit(message):
    """Handles the 'exit' command."""
    print("Exiting server...")
    stop_server()

def handle_help(message):
    """Handles the 'help' command."""
    print_help()

# --- Signal Handlers ---

def signal_handler(sig, frame):
    """Handles system signals (e.g., Ctrl+C)."""
    print("\nSignal received. Shutting down...")
    stop_server()

# --- Command Dispatch ---

command_handlers = {
    "start": handle_start,
    "help": handle_help,
    "display": handle_display,
    "exit": handle_exit,
    "write": handle_write
}

# --- Main Execution ---

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if len(sys.argv) > 1:
        # Command-line argument parsing
        if sys.argv[1] == "-s":
            start_server()
        elif sys.argv[1] == "-h" or sys.argv[1] == "--help":
            print_help()
        else:
            print("Unknown command. Try 'python script.py --help'.")
    else:
        # Keep the server running until interrupted
        while True:
            time.sleep(1)

