import RPi.GPIO as GPIO
import time
import requests

# GPIO pin connected to the voltage sensor
VOLTAGE_SENSOR_PIN = 17

# Alert destination URL
ALERT_ENDPOINT = "http://example.com/alert"


def setup_gpio(pin):
    """Configure the GPIO pin for voltage monitoring."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)


def read_voltage_status(pin):
    """Read the voltage sensor and return True for power, False for failure."""
    return GPIO.input(pin) == GPIO.HIGH


def send_power_failure_alert(url):
    """Send an HTTP POST alert when power fails."""
    try:
        requests.post(url, json={"alert": "Power failure detected"})
    except requests.exceptions.RequestException as request_error:
        print("Alert failed:", request_error)


def monitor_power(pin, alert_url):
    """Continuously monitor power and send alerts on failure."""
    try:
        while True:
            if not read_voltage_status(pin):
                send_power_failure_alert(alert_url)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Monitoring stopped")
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    setup_gpio(VOLTAGE_SENSOR_PIN)
    monitor_power(VOLTAGE_SENSOR_PIN, ALERT_ENDPOINT)

