# Simple sentiment analysis demo for Raspberry Pi
# Uses a hardcoded lexicon and LED feedback (if available)

import time
import sys
try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not found, running without LED feedback")
    GPIO = None

# Sentiment lexicon (words and their polarity scores)
vader_lexicon = {
    "happy": 0.5, "good": 0.3, "great": 0.7, "sad": -0.4, "bad": -0.6, "terrible": -0.9
}

def analyze_sentiment(sentence):
    """Analyzes the sentiment of a sentence."""
    words = sentence.lower().split()
    total_score = 0.0
    for word in words:
        if word in vader_lexicon:
            total_score += vader_lexicon[word]
    average_score = total_score / len(words) if words else 0.0
    return average_score

def classify_sentiment(score):
    """Classifies the sentiment based on the score."""
    if score > 0.2:
        return "Positive"
    elif score < -0.2:
        return "Negative"
    else:
        return "Neutral"

def main():
    """Main function to get input and analyze sentiment."""
    try:
        user_input = input("Enter a sentence: ")
        sentiment_score = analyze_sentiment(user_input)
        sentiment_label = classify_sentiment(sentiment_score)
        print("Sentiment:", sentiment_label, "Score:", sentiment_score)
        if GPIO:
            # Control LEDs (example)
            GPIO.output(17, sentiment_label == "Positive")
            GPIO.output(18, sentiment_label == "Negative")
            time.sleep(2)
            GPIO.output(17, GPIO.LOW)
            GPIO.output(18, GPIO.LOW)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        if GPIO:
            GPIO.cleanup() # Clean up GPIO on exit

if __name__ == "__main__":
    main()

