import logging
from worker_K10CR1 import WK10CR1
from worker_DAC8532 import WDAC8532
from typing import Callable, Any, Dict, List, Union
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SubscriptionHandler:
    """
    Handles subscriptions to data streams and manages callbacks.
    """

    def __init__(self, logger: logging.Logger, monitor: Callable[[Dict[str, Any]], None]) -> None:
        """
        Initializes the SubscriptionHandler.

        Args:
            logger: Logger instance for logging.
            monitor: Function to monitor subscriptions and unsubscriptions.
        """
        self.logger = logger
        self.subscriptions: Dict[str, List[Dict[str, Any]]] = {}  # {stream_filter: [callback_info]}
        self.channel_info: Dict[str, Dict[str, Any]] = {}  # {channel_id: {kwargs, control}}
        self.monitor_func = monitor
        self.subscriber_socket: zmq.Socket = None

    def handle_command(self, command: dict) -> None:
        """
        Handles commands related to subscriptions and control.

        Args:
            command: A dictionary containing the command details.
                     Expected keys: 'action', 'stream_filter', 'callback', 'kwargs', 'id'
        """
        action = command.get('action')

        if not action:
            self.logger.error("Missing 'action' key in command.")
            return

        stream_filter = command.get('stream_filter')

        if action == 'SUBSCRIBE':
            self._subscribe(command)
        elif action == 'UPDATE_KW':
            self._update_kwargs(command)
        elif action == 'UNSUBSCRIBE':
            self._unsubscribe(command)
        elif action == 'REMOVE_ALL_CBS':
            self._remove_all_callbacks(command)
        elif action == 'RESET':
            self._reset_channel(command)
        elif action == 'RESET_ALL':
            self._reset_all_channels(command)
        elif action in ('MUTE', 'UNMUTE'):
            self._mute_channel(command)
        elif action in ('MUTE_ALL', 'UNMUTE_ALL'):
            self._mute_all_channels(command)
        elif action in ('PAUSE', 'RESTART'):
            self._pause_channel(command)
        elif action in ('PAUSE_ALL', 'RESTART_ALL'):
            self._pause_all_channels(command)
        else:
            self.logger.warning(f"Unknown action: {action}")

        self.monitor_func(self.channel_info)

    def _subscribe(self, command: dict) -> None:
        """Subscribes to a data stream."""
        stream_filter = command.get('stream_filter')
        callback = command.get('callback')
        kwargs = command.get('kwargs', {})
        callback_id = command.get('id')

        if not all([stream_filter, callback]):
            self.logger.error("Missing 'stream_filter' or 'callback' in subscribe command.")
            return

        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
            if self.subscriber_socket:  # Check if socket is initialized
                self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
            self.logger.info(f"Subscribed to stream filter: {stream_filter}")

        self.subscriptions[stream_filter].append({
            'callback': callback,
            'kwargs': kwargs,
            'state': {},
            'control': {'alert': True, 'pause': False},
            'id': callback_id
        })
        self.channel_info[callback_id] = {
            'kwargs': kwargs,
            'control': {'alert': True, 'pause': False}
        }

        self.monitor_func(self.channel_info)

    def _unsubscribe(self, command: dict) -> None:
        """Unsubscribes from a data stream."""
        stream_filter = command.get('stream_filter')
        if stream_filter in self.subscriptions:
            if self.subscriber_socket:
                self.subscriber_socket.setsockopt_string(zmq.UNSUBSCRIBE, stream_filter)
            del self.subscriptions[stream_filter]
            self.logger.info(f"Unsubscribed from stream filter: {stream_filter}")
        else:
            self.logger.warning(f"Not subscribed to stream filter: {stream_filter}")

    def _update_kwargs(self, command: dict) -> None:
        """Updates the keyword arguments for a specific channel."""
        callback_id = command.get('id')
        new_kwargs = command.get('kwargs', {})

        if callback_id in self.channel_info:
            self.channel_info[callback_id]['kwargs'] = new_kwargs
            self.logger.info(f"Updated kwargs for channel {callback_id} to {new_kwargs}")
        else:
            self.logger.warning(f"Channel with id {callback_id} not found.")

    def _remove_all_callbacks(self, command: dict) -> None:
        """Removes all callbacks for a specific stream filter."""
        stream_filter = command.get('stream_filter')
        if stream_filter in self.subscriptions:
            self.subscriptions[stream_filter] = []
            self.logger.info(f"Removed all callbacks for stream filter: {stream_filter}")
        else:
            self.logger.warning(f"Not subscribed to stream filter: {stream_filter}")

    def _reset_channel(self, command: dict) -> None:
        """Resets the state of a specific channel."""
        callback_id = command.get('id')
        for callback in self.subscriptions.get(command.get('stream_filter'), []):
            if callback['id'] == callback_id:
                callback['state'] = {}
                self.logger.info(f"Resetted channel {callback_id} state.")
                break

    def _reset_all_channels(self, command: dict) -> None:
        """Resets the state of all channels for a specific stream filter."""
        stream_filter = command.get('stream_filter')
        if stream_filter in self.subscriptions:
            for callback in self.subscriptions[stream_filter]:
                callback['state'] = {}
            self.logger.info(f"Resetted all channels for stream filter: {stream_filter}")
        else:
            self.logger.warning(f"Not subscribed to stream filter: {stream_filter}")

    def _mute_channel(self, command: dict) -> None:
        """Mutes or unmutes a specific channel."""
        callback_id = command.get('id')
        channel = next((c for c in self.subscriptions.get(command.get('stream_filter'), [])
                        if c['id'] == callback_id), None)

        if channel:
            channel['control']['alert'] = not channel['control']['alert']
            self.logger.info(f"Channel {callback_id} alert {'enabled' if channel['control']['alert'] else 'disabled'}")
        else:
            self.logger.warning(f"Channel with id {callback_id} not found.")

    def _mute_all_channels(self, command: dict) -> None:
        """Mutes or unmutes all channels for a specific stream filter."""
        stream_filter = command.get('stream_filter')
        muted = not bool(self.channel_info.get(command.get('id', None)))
        if stream_filter in self.subscriptions:
            for callback in self.subscriptions[stream_filter]:
                callback['control']['alert'] = muted
                self.channel_info[callback['id']] = {'control': callback['control']}
            self.logger.info(f"All channels for stream filter: {stream_filter} {'muted' if muted else 'unmuted'}")

    def _pause_channel(self, command: dict) -> None:
        """Pauses or restarts a specific channel."""
        callback_id = command.get('id')
        channel = next((c for c in self.subscriptions.get(command.get('stream_filter'), [])
                        if c['id'] == callback_id), None)

        if channel:
            channel['control']['pause'] = not channel['control']['pause']
            self.logger.info(f"Channel {callback_id} paused {'restarted' if channel['control']['pause'] else 'paused'}")
        else:
            self.logger.warning(f"Channel with id {callback_id} not found.")

    def _pause_all_channels(self, command: dict) -> None:
        """Pauses or restarts all channels for a specific stream filter."""
        stream_filter = command.get('stream_filter')
        paused = not bool(self.channel_info.get(command.get('id', None)))
        if stream_filter in self.subscriptions:
            for callback in self.subscriptions[stream_filter]:
                callback['control']['pause'] = paused
                self.channel_info[callback['id']] = {'control': callback['control']}
            self.logger.info(f"All channels for stream filter: {stream_filter} {'paused' if paused else 'restarted'}")

    def handle_message(self, message: str) -> None:
        """
        Handles incoming messages from the data stream.

        Args:
            message: The incoming message.
        """
        try:
            stream_filter, data = message.split(" ", 1) # Ensure proper splitting
            data = json.loads(data)

            if stream_filter in self.subscriptions:
                for callback in self.subscriptions[stream_filter]:
                    if not callback['control']['pause']:  # Check control['pause'] after subscription handling
                        callback['state'] = data
                        self.logger.debug(f"Processed state for channel {callback['id']} with data: {data}")

                        # Here you could trigger actions based on the data
                        # Example: update a display, send an email, etc.
        except (ValueError, json.JSONDecodeError) as e:
            self.logger.error(f"Error handling message: {e}. Message: {message}")


class PIDHandler:
    """
    Manages PID controllers and error handling.
    """

    def __init__(self, logger: logging.Logger, config: Dict[str, Any] = None) -> None:
        """
        Initializes the PIDHandler.

        Args:
            logger: Logger instance for logging.
            config: Configuration parameters.
        """
        self.logger = logger
        self.config = config if config else {}
        self.global_err_state = False
        self.last_msg = time.time()
        self.pid_controller: Union[WK10CR1, WDAC8532] = None
        self.subscriber_handler = SubscriptionHandler(self.logger, self.handle_message)

        if self.config.get('controller', 'WK10CR1').lower() == 'wk10cr1':
            self.pid_controller = WK10CR1(self.config['controller']['WK10CR1'])
        elif self.config.get('controller', 'WDAC8532').lower() == 'dac8532':
            self.pid_controller = WDAC8532(self.config['controller']['DAC8532'])
        else:
            self.logger.error("Invalid controller configuration.")
            raise ValueError("Invalid controller configuration.")

        self.subscriber_socket = None  # Initialize later to handle potential None values

    def handle_message(self, message: str) -> None:
        """
        Handles incoming messages and updates PID controller.

        Args:
            message: The incoming message.
        """
        try:
            data = json.loads(message)
            if 'target' in data:
                self.pid_controller.set_setpoint(data['target'])
            elif 'error' in data:
                self.global_err_state = bool(data['error'])  # Set global err state directly
            self.subscriber_handler.handle_message(message)
        except (ValueError, json.JSONDecodeError) as e:
            self.logger.error(f"Error processing message: {e}. Message: {message}")
            self.subscriber_handler.handle_message(message)  # Forward to handler even with errors

    def update_error_output(self, error: bool) -> None:
        """
        Updates the error output based on the global error state.

        Args:
            error: The current error state.
        """
        if self.subscriber_socket:  # Check if socket is initialized
            self.subscriber_socket.setsockopt_string(zmq.LINGER, 0)
            self.subscriber_socket.setsockopt_string(zmq.PING, "PING")
            try:
                self.subscriber_socket.recv_string(zmq.NOBLOCK)
            except zmq.ZMQError as e:
                if e.code == zmq.EAGAIN:
                    self.handle_watchdog_timeout()
                else:
                    self.logger.error(f"Unexpected ZMQ error during error output update: {e}")
                    return
            finally:
                self.subscriber_socket.setsockopt_string(zmq.PING, "")

        if error != self.global_err_state:
            self.global_err_state = error
            error_output = "ERROR" if error else "OK"
            self.subscriber_handler.set_error_output(error_output)

    def handle_watchdog_timeout(self) -> None:
        """
        Handles watchdog timeout by triggering the error output."""
        self.logger.error("Watchdog timeout triggered. Triggering error output.")
        self.global_err_state = True
        if self.subscriber_socket:
            self.subscriber_socket.setsockopt_string(zmq.LINGER, 0)
            self.subscriber_socket.setsockopt_string(zmq.PING, "PING")
            try:
                self.subscriber_socket.recv_string(zmq.NOBLOCK)
            except zmq.ZMQError as e:
                if e.code == zmq.EAGAIN:
                    self.handle_watchdog_timeout() # Recurse for additional pings if needed
                else:
                    self.logger.error(f"Unexpected ZMQ error during watchdog timeout handling: {e}")
            finally:
                self.subscriber_socket.setsockopt_string(zmq.PING, "")

    def connect_to_zmq(self, context: zmq.Context, logger: logging.Logger = None) -> None:
        """
        Connects to the ZMQ context and sets up subscriptions.

        Args:
            context: The ZMQ context.
            logger: Logger instance (optional).
        """
        self.logger = logger or logging.getLogger(__name__)
        self.subscriber_socket = context.socket(zmq.SUBSCRIBE)
        self.subscriber_socket.setsockopt(zmq.LINGER, 0)

        self.subscriber_socket.connect('ASTERISK')
        self.subscriber_socket.setsockopt_string(zmq.PING, "")

        self.subscriber_handler.monitor_func = partial(self.handle_message, logger=self.logger) # Partial application

        self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, self.config.get('stream_filter', ''))

    def start(self) -> None:
        """
        Starts the PID controller and sets up error output.

        Returns:
            A function to stop the PID controller.
        """
        self.pid_controller.start()

        def stop_pid_controller(signal: signal.Signals, frame) -> None:
            """Handles SIGINT and SIGTERM signals for graceful shutdown."""
            self.logger.info("Stopping PID controller and exiting.")
            self.pid_controller.stop()
            if self.subscriber_socket:
                self.subscriber_socket.close()
            GPIO.cleanup()
            sys.exit(0)

        signal.signal(signal.SIGINT, stop_pid_controller)
        signal.signal(signal.SIGTERM, stop_pid_controller)

        return stop_pid_controller

    def set_error_output(self, output: Union[int, str]) -> None:
        """
        Sets the error output.

        Args:
            output: The desired error output (integer for DAC8532, string for other outputs).
        """
        if self.subscriber_socket:
            self.subscriber_socket.setsockopt_string(zmq.LINGER, 0)
            self.subscriber_socket.setsockopt_string(zmq.PING, "PING")
            try:
                self.subscriber_socket.recv_string(zmq.NOBLOCK)
            except zmq.ZMQError as e:
                if e.code == zmq.EAGAIN:
                    self.handle_watchdog_timeout()
                else:
                    self.logger.error(f"Unexpected ZMQ error during error output set: {e}")
            finally:
                self.subscriber_socket.setsockopt_string(zmq.PING, "")

        if output != self.subscriber_handler.get_error_output():
            self.subscriber_handler.set_error_output(output)

    def cleanup(self) -> None:
        """
        Cleans up resources.
        """
        if self.subscriber_socket:
            self.subscriber_socket.close()
            self.subscriber_socket = None
        GPIO.cleanup()


def main() -> None:
    """Entry point for running the PID handler."""
    context: zmq.Context = zmq.Context()
    handler = PIDHandler(context, config={
        'stream_filter': 'Control',
        'controller': {'WK10CR1': 100, 'DAC8532': 50}
    })

    def mock_monitor(channel_info: Dict[str, Any]) -> None:
        """Mock monitor function."""
        logging.info(f"Channel info: {channel_info}")

    handler.subscriber_handler.monitor_func = mock_monitor

    handler.connect_to_zmq(context)

    stop = handler.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        stop()


if __name__ == '__main__':
    main()

