# Wildlife tracking IoT remote control server on a Raspberry Pi
# Listens for remote control commands over a TCP socket
# Supports starting/stopping tracking and reporting GPS coordinates
import socket
import json
import time
import logging
import signal
import sys
from collections import deque

# Configure logging for the wildlife tracking IoT server
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Remote control command set for the wildlife tracking system
COMMAND_SET = {
    "start": "track_running",
    "stop": "track_idle",
    "report": "return_coordinates",
}

# GPS module factory that returns a mock object if hardware is unavailable
class GPSModuleFactory:
    """Factory that selects the appropriate GPS module for the Raspberry Pi."""

    def __init__(self, device_path, i2c_address):
        """Store the device path and I2C address for later use."""
        self.device_path = device_path
        self.i2c_address = i2c_address

    def create(self):
        """Create and return a GPS module instance based on the factory settings."""
        if self.device_path:
            # Attempt to open the serial device for a UART GPS module
            try:
                import serial
                return serial.Serial(self.device_path, 9600, timeout=1)
            except serial.SerialException:
                logging.warning("Serial GPS device unavailable, falling back to I2C")
        else:
            # Attempt to open the I2C device for an I2C GPS module
            try:
                import smbus2
                bus = smbus2.SMBus(1)
                return bus
            except OSError:
                logging.warning("I2C GPS device unavailable, falling back to simulation")
        return None

    def close(self, module):
        """Close the underlying GPS module."""
        if module:
            module.close()


class WildlifeTracker:
    """A remote control server for a wildlife tracking IoT system."""

    def __init__(self, device_path, i2c_address, log_level=logging.INFO):
        """Initialize the tracker with a device path and I2C address."""
        self.device_path = device_path
        self.i2c_address = i2c_address
        self.gps_module = GPSModuleFactory(device_path, i2c_address).create()
        self.running = False
        self.command_queue = deque(maxlen=10)
        self.logger = logging.getLogger("wildlife_tracker")
        self.logger.setLevel(log_level)

    def read_gps_position(self):
        """Read the current GPS coordinates from the underlying module."""
        if self.gps_module:
            try:
                # Read a position line from the GPS module
                position_line = self.gps_module.readline().decode("utf-8", errors="ignore").strip()
                if position_line:
                    latitude, longitude = position_line.split(",")
                    return float(latitude), float(longitude)
                return None, None
            except (IOError, OSError) as read_error:
                self.logger.error("GPS read failed: %s", read_error)
                return None, None
        else:
            # Simulate GPS coordinates when no module is available
            return 37.7749, -122.4194

    def handle_command(self, command_text):
        """Apply a remote control command to the wildlife tracking state."""
        if command_text in COMMAND_SET:
            action = COMMAND_SET[command_text]
            if action == "track_running":
                self.running = True
                self.logger.info("Tracking running")
            elif action == "track_idle":
                self.running = False
                self.logger.info("Stopped tracking")
            elif action == "return_coordinates":
                latitude, longitude = self.read_gps_position()
                if latitude is not None and longitude is not None:
                    response = json.dumps({"lat": latitude, "lon": longitude})
                    self.logger.info("Returned coordinates: %s", response)
                else:
                    self.logger.warning("Could not read GPS coordinates")
            else:
                self.logger.warning("Unknown command: %s", command_text)
        else:
            self.logger.warning("Unknown command: %s", command_text)

    def accept_connection(self, client_socket, client_address):
        """Accept a single remote control connection and dispatch it."""
        try:
            # Read the command text from the client socket
            command_text = client_socket.recv(1024).decode("utf-8", errors="ignore").strip()
            if command_text:
                self.command_queue.append((client_socket, client_address, command_text))
                client_socket.sendall(b"Command received")
            else:
                client_socket.sendall(b"Connection closed")
        except OSError as recv_error:
            self.logger.error("Connection error: %s", recv_error)
        finally:
            client_socket.close()

    def run_server(self, host="127.0.0.1", port=9099, backlog=1):
        """Run the remote control server and handle incoming connections."""
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((host, port))
        server_socket.listen(backlog)
        server_socket.settimeout(2)

        self.logger.info("Wildlife tracking server listening on %s:%s", host, port)

        try:
            while True:
                try:
                    client_socket, client_address = server_socket.accept()
                    self.accept_connection(client_socket, client_address)
                except socket.timeout:
                    # No connection received within the timeout window
                    continue
                except OSError as accept_error:
                    self.logger.error("Accept error: %s", accept_error)
        except KeyboardInterrupt:
            self.logger.info("Shutting down wildlife tracking server")
        finally:
            server_socket.close()


def signal_handler(signum, frame):
    """Handle shutdown signals for the wildlife tracking server."""
    logging.info("Received shutdown signal")
    sys.exit(0)


if __name__ == "__main__":
    # Run the wildlife tracking remote control server on the Raspberry Pi
    tracker = WildlifeTracker(device_path="/dev/ttyUSB0", i2c_address=0x42)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    tracker.run_server()

