import pigpio
import time

class MotorError(Exception):
    """Custom exception for motor control errors."""

    pass

class Motor:
    """Control a DC motor driven through an H-bridge on a Raspberry Pi."""

    def __init__(self, pi_connection, motor_pin, frequency_hz=1000):
        """Set up the motor pin and frequency on the Pi connection."""
        if not isinstance(pi_connection, pigpio.pi):
            raise MotorError("pi connection must be a pigpio.pi instance")
        self.pi_connection = pi_connection
        self.motor_pin = motor_pin
        self.frequency_hz = frequency_hz
        self.current_frequency = None
        try:
            self.pi_connection.set_mode(self.motor_pin, pigpio.OUTPUT)
            self.pi_connection.write(self.motor_pin, 0)
            self.stop()
        except pigpio.error as e:
            raise MotorError(f"pigpio error: {e}")

    def set_frequency(self, frequency_hz):
        """Set the PWM frequency for the motor."""
        if self.current_frequency_hz != self.frequency_hz:
            self.current_frequency_hz = self.frequency_hz
            try:
                self.pi_connection.set_PWM_frequency(self.motor_pin, self.current_frequency_hz)
                self.current_frequency = self.current_frequency_hz
            except pigpio.error as e:
                raise MotorError(f"pigpio error setting frequency: {e}")

    def set_duty_cycle(self, duty_cycle_percent):
        """Set the PWM duty cycle for the motor."""
        if not 0 <= duty_cycle_percent <= 255:
            raise MotorError("duty cycle must be between 0 and 255")
        try:
            duty_cycle = int(duty_cycle_percent)
            self.pi_connection.set_PWM_dutycycle(self.motor_pin, duty_cycle)
            self.current_duty_cycle = duty_cycle
        except pigpio.error as e:
            raise MotorError(f"pigpio error setting duty cycle: {e}")

    def stop(self):
        """Stop the motor by setting duty cycle to 0."""
        self.set_duty_cycle(0)

    def close(self):
        """Release the motor pin."""
        self.pi_connection.write(self.motor_pin, 0)
        self.pi_connection.set_mode(self.motor_pin, pigpio.INPUT)


def main():
    """Create a motor object and demonstrate frequency and duty cycle changes."""
    pi_connection = pigpio.pi()
    try:
        motor1 = Motor(pi_connection, 18)
        motor1.set_frequency(1200)
        motor1.set_duty_cycle(128)
        time.sleep(1)
        motor1.stop()
    except MotorError as e:
        print(f"Motor error occurred: {e}")
    finally:
        if 'pi_connection' in locals():
            pi_connection.stop()


if __name__ == "__main__":
    main()

