#!/usr/bin/env python3
"""
Controls a vibration motor on a Raspberry Pi via GPIO using gpiozero.
Vibration is scheduled to occur at a fixed time daily.
"""

import time
import signal
import logging
from gpiozero import OutputDevice
from schedule import Schedule, ScheduleError
from datetime import datetime

# Configure logging for the vibration controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
logger = logging.getLogger(__name__)

# GPIO pin connected to the vibration motor driver (BCM numbering)
VIBRATION_MOTOR_PIN = 17

# Duration for which the motor should vibrate in seconds
VIBRATION_DURATION = 30


def activate_vibration_motor(motor_device):
    """Activates the vibration motor for a fixed duration."""
    try:
        motor_device.on()
        logger.info("Vibration motor activated for %d seconds", VIBRATION_DURATION)
    except Exception as e:
        logger.error("Error activating motor: %s", e)


def deactivate_vibration_motor(motor_device):
    """Deactivates the vibration motor."""
    try:
        motor_device.off()
        logger.info("Vibration motor deactivated")
    except Exception as e:
        logger.error("Error deactivating motor: %s", e)


def vibration_job(motor_device):
    """Job function that activates and deactivates the motor."""
    try:
        activate_vibration_motor(motor_device)
        time.sleep(VIBRATION_DURATION)
        deactivate_vibration_motor(motor_device)
    except Exception as e:
        logger.error("Vibration job failed: %s", e)


def setup_gpio():
    """Initializes the GPIO pin for the vibration motor."""
    try:
        motor_device = OutputDevice(VIBRATION_MOTOR_PIN, active_high=True, initial_value=False)
        logger.info("Vibration motor initialized on GPIO %d", VIBRATION_MOTOR_PIN)
        return motor_device
    except Exception as e:
        logger.error("GPIO initialization failed: %s", e)
        raise  # Re-raise the exception to halt execution


def main():
    """Main entry point: schedules and runs the vibration job."""
    try:
        motor_device = setup_gpio()
        schedule = Schedule(vibration_job, minute=14, hour=21)
        schedule.run(datestr="now", delay=0)
    except ScheduleError as e:
        logger.error("Schedule error: %s", e)
    except KeyboardInterrupt:
        logger.info("Vibration controller stopped by user")
    except Exception as e:
        logger.exception("Unhandled exception in main: %s", e)
    finally:
        if 'motor_device' in locals():
            try:
                motor_device.off()  # Ensure motor is off on exit
            except Exception:
                pass
        logger.info("Vibration motor cleanup complete")


if __name__ == "__main__":
    main()

