# hydroponics control intent parser for a Raspberry Pi
# Recognizes simple phrases and drives gpiozero actuators
import time
from gpiozero import OutputDevice

# BCM pins for the hydroponics actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Map intents to gpiozero OutputDevice objects
actuators = {
    "pump_on": OutputDevice(PUMP_PIN, active_high=True, initial_value=False),
    "pump_off": OutputDevice(PUMP_PIN, active_high=True, initial_value=True),
    "light_on": OutputDevice(LIGHT_PIN, active_high=True, initial_value=False),
    "light_off": OutputDevice(LIGHT_PIN, active_high=True, initial_value=True),
}


def parse_phrase(phrase):
    """Parse a phrase into hydroponics control intents."""
    # Case-insensitive keyword matching for intent recognition
    keywords = {"turn", "pump", "on", "off", "light", "switch"}
    intent = None
    for keyword in keywords:
        if keyword.lower() in phrase.lower():
            intent = keyword.capitalize()
            break
    return intent


def apply_intent(intent):
    """Apply the recognized intent to the actuators."""
    # Dispatch the recognized intent to the appropriate action
    if intent in actuators:
        action = actuators[intent]
        action.on()
        return intent
    return None


def main():
    """Process a list of test phrases for hydroponics control."""
    try:
        # Initialize the actuators before processing phrases
        for device in actuators.values():
            device.close()
        for device in actuators.values():
            device = OutputDevice(device.pin, active_high=True, initial_value=device.initial_value)
            device.close()
        test_phrases = [
            "turn the pump on",
            "switch the light",
            "turn pump off",
            "turn pump on",
            "unknown command",
        ]
        for phrase in test_phrases:
            intent = parse_phrase(phrase)
            if intent:
                applied_intent = apply_intent(intent)
                if applied_intent:
                    print("Applied intent:", applied_intent)
                else:
                    print("No intent recognized for:", phrase)
            else:
                print("No intent recognized for:", phrase)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Hydroponics control stopped")
    finally:
        # Ensure all actuators are off on shutdown
        for device in actuators.values():
            device.off()
        print("Actuators off")


if __name__ == "__main__":
    main()

