import smbus2
import contextlib

# I2C device helper for the Raspberry Pi using smbus2
class I2CDevice:
    """Wrap an I2C bus and provide robust I2C operations."""

    def __init__(self, address, bus_number=1):
        """Open the I2C bus and verify the device is present."""
        # Open the smbus2 bus at the configured bus number
        self.bus_number = bus_number
        try:
            self.bus = smbus2.SMBus(bus_number)
        except OSError:
            raise RuntimeError("I2C bus unavailable")
        self.address = address
        # Probe the device to ensure it acknowledges pings
        self._verify_device_presence()
        self.closed = False

    def _verify_device_presence(self):
        """Send a few pings to confirm the device is present."""
        try:
            self.bus.read_byte(self.address)
        except OSError:
            raise RuntimeError("No device found at address 0x%02X" % self.address)

    @contextlib.contextmanager
    def wrap_bus(self):
        """Context manager wrapper around the smbus2 bus."""
        if self.closed:
            raise RuntimeError("I2C bus already closed")
        try:
            yield self.bus
        finally:
            self.close()

    def write_byte(self, register, value):
        """Write a single byte value to an I2C register."""
        # Use the wrapped bus to perform the write operation
        with self.wrap_bus() as bus:
            bus.write_byte_data(self.address, register, value)

    def read_byte(self, register):
        """Read a single byte value from an I2C register."""
        # Use the wrapped bus to perform the read operation
        with self.wrap_bus() as bus:
            return bus.read_byte_data(self.address, register)

    def close(self):
        """Close the underlying I2C bus."""
        # Mark the bus as closed for later callers
        self.closed = True

    def __enter__(self):
        """Context manager entry point."""
        return self.wrap_bus()

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point that closes the bus."""
        if self.closed:
            self.close()


def main():
    """Example usage of the I2C device helper."""
    # Example address and register for a Raspberry Pi I2C device
    i2c_device = I2CDevice(address=0x40, bus_number=1)
    try:
        # Write a value to register 0x00
        i2c_device.write_byte(0x00, 0x55)
        # Read a value back from the same register
        result = i2c_device.read_byte(0x00)
        print("Wrote 0x55, read back 0x%02X" % result)
    except RuntimeError as device_error:
        print("I2C device error:", device_error)
    finally:
        # Ensure the bus is closed when finished
        i2c_device.close()


if __name__ == "__main__":
    main()

