import smbus2
from datetime import datetime
import contextlib

# DS1338 RTC I2C address
DS1338_ADDRESS = 0x68

# Register addresses (organized by category)
REGISTER_NAMES = {
    "control": 0x00,
    "seconds": 0x00,
    "minutes": 0x01,
    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
}

# Bit masks for register values (BCD encoding)
BIT_MASKS = {
    "control": 0x80,
    "hours": 0x40,
    "day": 0x20,
    "date": 0x10,
    "month": 0x08,
    "year": 0x04,
}


@contextlib.contextmanager
def ds1338_i2c_bus():
    """Context manager for DS1338 I2C bus."""
    bus = smbus2.SMBus(1)  # Use I2C bus 1 on Raspberry Pi
    try:
        yield bus
    finally:
        bus.close()


class DS1338:
    """Driver for the DS1338 RTC chip."""

    def __init__(self, address=DS1338_ADDRESS, bus_num=1):
        """Initialize the DS1338 object.

        Args:
            address (int): The I2C address of the DS1338.
            bus_num (int): The I2C bus number.
        """
        self.address = address
        self.bus_number = bus_num
        with ds1338_i2c_bus() as bus:
            self.bus = bus

    def _read_register(self, register_name, signed=False):
        """Read a byte from a register."""
        try:
            return self.bus.read_byte_data(self.address, register_name)
        except IOError as e:
            raise IOError(f"Error reading register {register_name:02X}: {e}")

    def _write_register(self, register_name, value, signed=False):
        """Write a byte to a register."""
        try:
            self.bus.write_byte_data(self.address, register_name, value)
        except IOError as e:
            raise IOError(f"Error writing to register {register_name:02X}: {e}")


    def read_all(self):
        """Read all register values."""
        try:
            return {name: self._read_register(register_name, signed=(name == "year")) for name in REGISTER_NAMES}
        except IOError as e:
            raise IOError(f"Error reading all registers: {e}")


    def read_datetime(self):
        """Return a datetime object."""
        try:
            data = self.read_all()
            # Convert BCD to decimal, handling two's complement for year
            year = 2000 + (data["year"] & 0x3F)
            month = data["month"] if 1 <= data["month"] <= 12 else 12
            date = data["date"] if 1 <= data["date"] <= 31 else 1
            day = data["day"] if 1 <= data["day"] <= 7 else 7
            hours = data["hours"] // 2 if 0 <= data["hours"] <= 12 else data["hours"] - 12
            minutes = data["minutes"] if 0 <= data["minutes"] <= 59 else 0
            seconds = data["seconds"] // 2 if 0 <= data["seconds"] <= 59 else 0
            return datetime(year, month, date, hours, minutes, seconds)
        except (KeyError, ValueError, TypeError) as e:
            raise IOError(f"Error constructing datetime: {e}")


    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all register values."""

        # Enforce 24-hour mode and validate ranges
        if not 0 <= hours <= 23: raise ValueError("Invalid hours value")
        if not 0 <= minutes <= 59: raise ValueError("Invalid minutes value")
        if not 0 <= seconds <= 59: raise ValueError("Invalid seconds value")

        data = {
            "year": year % 100, "month": month, "date": date, "day": day,
            "hours": (hours * 2) % 64, "minutes": minutes, "seconds": seconds
        }

        try:
            for name, value in data.items():
                self._write_register(REGISTER_NAMES[name], value, signed=(name == "year"))
        except IOError as e:
            raise IOError(f"Error writing all registers: {e}")


    def write_datetime(self, dt):
        """Write a datetime object to the RTC."""
        try:
            self.write_all(dt.year, dt.month, dt.day, dt.isoweekday(),
                           dt.hour, dt.minute, dt.second)
        except (ValueError, TypeError) as e:
            raise IOError(f"Invalid datetime object: {e}")


    def write_now(self):
        """Write the current system time to the RTC."""
        now = datetime.now()
        self.write_datetime(now)

