# Radiation monitoring station for Raspberry Pi using a UART sensor
# Reads µSv/h values from a UART serial port and triggers an alarm on high levels
import serial
import time
import RPi.GPIO as GPIO
import gpiozero

# Serial port configuration for the radiation sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1  # seconds

# Alarm pin on the Raspberry Pi GPIO header
ALARM_GPIO_PIN = 18

# Radiation threshold for the alarm (µSv/h)
RADIATION_THRESHOLD = 50.0


def open_serial_port(port, baudrate, timeout):
    """Open and return a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_radiation_level(serial_port):
    """Read one line from the serial port and parse it as a radiation level."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print("Skipping invalid radiation reading")
        return None
    except Exception as e:
        print(f"Error reading radiation level: {e}")
        return None


def set_alarm_state(alarm_pin, level, threshold):
    """Drive the alarm pin HIGH when the radiation level exceeds the threshold."""
    if level is not None:
        alarm_active = level > threshold
        alarm_pin.value = alarm_active
        if alarm_active:
            print("Alarm triggered: radiation level exceeded threshold")
        else:
            print("Alarm cleared: radiation level is within safe limits")


def main():
    """Main entry point: open the serial port, read radiation levels, and drive the alarm."""
    # Initialize the GPIO header and alarm pin
    GPIO.setmode(GPIO.BCM)
    alarm_pin = gpiozero.OutputDevice(ALARM_GPIO_PIN, active_high=True, initial_value=False)

    serial_port = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        return

    try:
        while True:
            # Read the radiation level from the serial port
            radiation_level = read_radiation_level(serial_port)

            # Update the alarm state based on the radiation level
            set_alarm_state(alarm_pin, radiation_level, RADIATION_THRESHOLD)

            # Wait before the next reading
            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("Stopping radiation monitoring station")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Close the serial port and release GPIO resources
        serial_port.close()
        GPIO.cleanup()


if __name__ == "__main__":
    main()

