import serial
import time
import RPi.GPIO as GPIO
from gpiozero import OutputDevice

# Serial port configuration for the flow sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

# GPIO pin for the alert indicator
ALERT_GPIO_PIN = 17

# Flow rate threshold in liters per minute
FLOW_THRESHOLD = 10.0


def open_serial_port(port, baudrate, timeout):
    """Opens a serial port."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_flow_rate(serial_port):
    """Reads a line from the serial port and parses it as a float."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor")
        return None
    except Exception as e:
        print(f"Error reading serial data: {e}")
        return None


def set_alert(gpio_pin, flow_rate, threshold):
    """Sets the alert GPIO pin based on the flow rate."""
    alert = OutputDevice(gpio_pin)
    if flow_rate > threshold:
        alert.on()
    else:
        alert.off()


def main():
    """Main function to read flow and trigger alerts."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        return

    GPIO.setmode(GPIO.BCM)
    set_alert(ALERT_GPIO_PIN, 0.0, FLOW_THRESHOLD)

    try:
        while True:
            flow_rate = read_flow_rate(serial_connection)
            if flow_rate is not None:
                print(f"Flow rate: {flow_rate:.2f} L/min")
                set_alert(ALERT_GPIO_PIN, flow_rate, FLOW_THRESHOLD)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources released")


if __name__ == "__main__":
    main()

