# Monitors a USB RFID reader on a Raspberry Pi and logs access events.
# Target: Raspberry Pi 3 Model B+
# Context: Smart retail access control

import serial
import time

# Serial port configuration for the RFID reader
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Log file path for access events
LOG_FILE = 'access_log.txt'


def open_serial_port(port, baudrate, timeout):
    """Opens and returns a serial port."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_rfid_tag(serial_port):
    """Reads an RFID tag ID from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        return data if data else None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def log_access_event(tag_id, log_file_path):
    """Logs an access event to the specified file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(log_file_path, 'a') as log_file:
            log_file.write(log_entry)
        return True
    except IOError as e:
        print(f"Error writing to log file: {e}")
        return False


def grant_access(tag_id):
    """Prints a grant message to the console."""
    print(f'Access granted for RFID Tag: {tag_id}')


def main():
    """Main function to monitor the RFID reader and log access events."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial port. Exiting.")
        return

    try:
        while True:
            tag_id = read_rfid_tag(serial_connection)
            if tag_id:
                if log_access_event(tag_id, LOG_FILE):
                    grant_access(tag_id)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Monitoring stopped by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

