# Reads heart rate and SpO2 from a pulse oximeter over serial on a Raspberry Pi

import serial
import time

# Serial port configuration for the pulse oximeter
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1

def open_serial_port(port, baudrate, timeout):
    """Open the serial port for the pulse oximeter."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_pulse_oximeter_data(serial_connection):
    """Read a line of data from the pulse oximeter and decode it."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        return line
    except UnicodeDecodeError:
        print("Error decoding data from pulse oximeter")
        return None

def process_pulse_oximeter_data(line):
    """Process the decoded line into heart rate and SpO2 values."""
    if line:
        try:
            heart_rate, spo2 = line.split(',')
            return heart_rate, int(spo2)
        except ValueError:
            print(f"Skipping line with invalid format: {line}")
            return None, None
    return None, None

def display_pulse_oximeter_data(heart_rate, spo2):
    """Print the heart rate and SpO2 values to the console."""
    if heart_rate is not None and spo2 is not None:
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main():
    """Main function to read and display pulse oximeter data."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_connection is None:
        return

    try:
        while True:
            line = read_pulse_oximeter_data(serial_connection)
            heart_rate, spo2 = process_pulse_oximeter_data(line)
            display_pulse_oximeter_data(heart_rate, spo2)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting pulse oximeter reader")
    finally:
        serial_connection.close()
        print("Serial port closed")

if __name__ == "__main__":
    main()

