    new_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1 # Handle empty list
    new_item = {"id": new_id, "name": name, "done": False}
    DATA_STORE.append(new_item)
    return jsonify(DATA_STORE)



