        if not body:
            return Response("No data received.", status=400, mimetype='text/plain')

        try:
            item_id = body.get('item_id', None)
            item_name = body.get('name', None)
            is_done = body.get('done', None)

            if item_name:
                new_item = {"id": DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1,
                            "name": item_name, "done": False}
                DATA_STORE.append(new_item)
                return jsonify(DATA_STORE)

            elif item_id is not None:
                # Update an existing item
                index = next((i for i, x in enumerate(DATA_STORE) if x['id'] == item_id), None)
                if index is not None:
                    DATA_STORE[index]['name'] = name  # Use 'name' key
                    return jsonify(DATA_STORE)
                else:
                    return Response(f"Item with id {item_id} not found.", status=404, mimetype='text/plain')

            else:
                return Response("Name is required.", status=400, mimetype='text/plain')

        except Exception as e:
            app.logger.error(f"Error processing POST data: {e}")
            return Response(f"Invalid data: {e}", status=500, mimetype='text/plain')


    else:  # GET request
        return get_data()


if __name__ == '__main__':
    import serial
    ser = initialize_serial(DEFAULT_SERIAL_PORT, DEFAULT_SERIAL_BAUDRATE)
    if ser:
        app.run(debug=True, host='0.0.0.0')
    else:
        app.run(debug=True, host='0.0.0.0')

